const Utils = {
 formatDate(dateStr, format) {
 const d = new Date(dateStr + 'T00:00:00');
 const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 const day = d.getDate();
 const month = months[d.getMonth()];
 const year = d.getFullYear();
 return `${month} ${String(day).padStart(2, '0')}, ${year}`;
 },
 escapeHtml(str) {
 const d = document.createElement('div');
 d.appendChild(document.createTextNode(str));
 return d.innerHTML;
 },
 groupBy(arr, fn) {
 return arr.reduce((acc, item) => {
 const key = fn(item);
 (acc[key] = acc[key] || []).push(item);
 return acc;
 }, {});
 },
 getPageParam(name) {
 return new URLSearchParams(window.location.search).get(name);
 },
 getCurrentPage() {
 let file = (window.location.pathname.split('/').pop() || 'index.html').toLowerCase();
 if (file === '' || file === '/') return 'index.html';
 if (!file.endsWith('.html')) file += '.html';
 return file;
 },
 getBasePath() {
 const path = window.location.pathname;
 const parts = path.split('/').filter(Boolean);
 const inPosts = path.includes('/posts/');
 return inPosts ? '../' : '';
 },
 resolveUrl(url, base) {
 if (!url) return '';
 if (/^(https?:)?\/\//.test(url) || url.startsWith('/')) return url;
 return base + url;
 }
};
function renderPostCard(post, base = '') {
 const date = Utils.formatDate(post.date);
 const tags = (post.tags || []).slice(0, 4).map(t =>
 `<a href="${base}tags.html?tag=${encodeURIComponent(t)}" class="tag">#${Utils.escapeHtml(t)}</a>`
 ).join('');
 const cats = (post.categories || []).map(c =>
 `<a href="${base}categories.html?cat=${encodeURIComponent(c)}" class="category-badge">${Utils.escapeHtml(c)}</a>`
 ).join('');
 const featBadge = post.featured
 ? `<span class="featured-badge">&#11088; Featured</span>`
 : '';
 return `
 <article class="post-card" itemscope itemtype="https://schema.org/BlogPosting">
 <div class="post-card-header">
 <div class="post-meta">
 <span class="post-date">&#128197; ${date}</span>
 ${post.readingTime ? `<span class="post-reading-time">&#9201; ${post.readingTime} min</span>` : ''}
 ${cats}
 </div>
 ${featBadge}
 </div>
 <h2 class="post-title" itemprop="headline">
 <a href="${base}${post.url}">${Utils.escapeHtml(post.title)}</a>
 </h2>
 <p class="post-excerpt" itemprop="description">${Utils.escapeHtml(post.excerpt)}</p>
 <div class="post-footer">
 <div class="post-tags">${tags}</div>
 <a href="${base}${post.url}" class="read-more" aria-label="Read ${post.title}">
 Read more <span aria-hidden="true">&#8594;</span>
 </a>
 </div>
 </article>`;
}
function renderPagination(total, current, perPage, container, onPageChange) {
 const totalPages = Math.ceil(total / perPage);
 if (totalPages <= 1) { container.innerHTML = ''; return; }
 let html = '';
 html += `<button class="page-btn" ${current <= 1 ? 'disabled' : ''}
 data-page="${current - 1}" aria-label="Previous page">&#8592; Prev</button>`;
 for (let i = 1; i <= totalPages; i++) {
 if (i === 1 || i === totalPages || Math.abs(i - current) <= 1) {
 html += `<button class="page-btn ${i === current ? 'active' : ''}"
 data-page="${i}" aria-label="Page ${i}" ${i === current ? 'aria-current="page"' : ''}>${i}</button>`;
 } else if (Math.abs(i - current) === 2) {
 html += `<span class="page-btn" style="cursor:default;opacity:0.5">…</span>`;
 }
 }
 html += `<button class="page-btn" ${current >= totalPages ? 'disabled' : ''}
 data-page="${current + 1}" aria-label="Next page">Next &#8594;</button>`;
 container.innerHTML = html;
 container.querySelectorAll('.page-btn[data-page]').forEach(btn => {
 btn.addEventListener('click', () => {
 const page = parseInt(btn.dataset.page);
 if (!isNaN(page) && page !== current) onPageChange(page);
 });
 });
}
function initHomePage() {
 const listEl = document.getElementById('postsList');
 const pageEl = document.getElementById('pagination');
 if (!listEl) return;
 const perPage = (typeof SITE_CONFIG !== 'undefined' && SITE_CONFIG.postsPerPage) || 5;
 let currentPage = 1;
 const sorted = [...POSTS_DATA].sort((a, b) => new Date(b.date) - new Date(a.date));
 function renderPage(page) {
 currentPage = page;
 const start = (page - 1) * perPage;
 const slice = sorted.slice(start, start + perPage);
 if (slice.length === 0) {
 listEl.innerHTML = `<div class="empty-state">
 <div class="empty-state-icon">📭</div>
 <p class="empty-state-text">No posts found.</p>
 </div>`;
 return;
 }
 listEl.innerHTML = slice.map(p => renderPostCard(p)).join('');
 listEl.querySelectorAll('.post-card').forEach((card, i) => {
 card.style.opacity = '0';
 card.style.transform = 'translateY(16px)';
 setTimeout(() => {
 card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
 card.style.opacity = '1';
 card.style.transform = 'translateY(0)';
 }, i * 60);
 });
 if (pageEl) renderPagination(sorted.length, page, perPage, pageEl, renderPage);
 window.scrollTo({ top: 0, behavior: 'smooth' });
 }
 renderPage(1);
}
function getSiteConfig() {
 return typeof SITE_CONFIG !== 'undefined' ? SITE_CONFIG : {};
}
function getConfigPath(obj, path) {
 return path.split('.').reduce((o, key) => (o == null ? undefined : o[key]), obj);
}
function applySiteMeta() {
 const cfg = getSiteConfig();
 const author = cfg.author || {};
 const base = Utils.getBasePath();
 const siteTitle = cfg.title || 'Blog';
 const titleEl = document.querySelector('title');
 const pageTitle = titleEl && titleEl.dataset.pageTitle;
 if (pageTitle === 'home' || pageTitle === '') {
 document.title = cfg.subtitle
 ? `${siteTitle} — ${cfg.subtitle}`
 : siteTitle;
 } else if (pageTitle) {
 document.title = `${pageTitle} | ${siteTitle}`;
 }
 let metaDesc = document.querySelector('meta[name="description"]');
 if (metaDesc && (!metaDesc.content || metaDesc.dataset.fromConfig === 'true')) {
 metaDesc.content = cfg.tagline
 ? `${cfg.tagline} — ${siteTitle}${author.name ? ' by ' + author.name : ''}`
 : siteTitle;
 }
 let metaAuthor = document.querySelector('meta[name="author"]');
 if (author.name) {
 if (!metaAuthor) {
 metaAuthor = document.createElement('meta');
 metaAuthor.name = 'author';
 document.head.appendChild(metaAuthor);
 }
 metaAuthor.content = author.name;
 }
 const ogTitle = document.querySelector('meta[property="og:title"]');
 if (ogTitle && (ogTitle.dataset.fromConfig === 'true' || !ogTitle.content)) {
 ogTitle.content = document.title;
 }
 const ogDesc = document.querySelector('meta[property="og:description"]');
 if (ogDesc && (ogDesc.dataset.fromConfig === 'true' || !ogDesc.content)) {
 ogDesc.content = cfg.tagline || '';
 }
 const icon = document.querySelector('link[rel="icon"]');
 if (icon && author.avatar) {
 icon.href = Utils.resolveUrl(author.avatar, base);
 }
}
