function applyConfigBindings() {
 const cfg = getSiteConfig();
 const base = Utils.getBasePath();
 document.querySelectorAll('[data-config]').forEach(el => {
 const path = el.getAttribute('data-config');
 const value = getConfigPath(cfg, path);
 if (value == null || value === '') return;
 if (el.tagName === 'IMG') {
 el.src = Utils.resolveUrl(value, base);
 if (!el.alt && cfg.author && cfg.author.name) el.alt = cfg.author.name;
 } else if (el.hasAttribute('data-config-attr')) {
 el.setAttribute(el.getAttribute('data-config-attr'), value);
 } else {
 el.textContent = value;
 }
 });
 document.querySelectorAll('[data-config-href]').forEach(el => {
 const value = getConfigPath(cfg, el.getAttribute('data-config-href'));
 if (value) el.setAttribute('href', value);
 });
 document.querySelectorAll('[data-config-mailto]').forEach(el => {
 const value = getConfigPath(cfg, el.getAttribute('data-config-mailto'));
 if (value) el.setAttribute('href', `mailto:${value}`);
 });
 document.querySelectorAll('[data-site-author]').forEach(el => {
 const name = (cfg.author && cfg.author.name) || '';
 el.innerHTML = `&#128104;&#8205;&#128187; ${Utils.escapeHtml(name)}`;
 });
}
